// LeadRescue | WF2 — Vapi Callback Parser + Intelligence Flagging
// Voice stack: Cartesia Sonic-3.6 + Deepgram Nova-3
// Audit v7: idempotency check, ghost customer SMS flag, 911 emergency flag
// Ghost threshold: 15s | Payload path: body.call.analysis.structuredData

const body = $input.first().json?.body ?? $input.first().json ?? {};

const callData = {
  vapiCallId:    body?.call?.id                                        ?? body?.id               ?? '',
  leadId:        body?.call?.assistantOverrides?.variableValues?.leadId ?? `LR-${Date.now()}`,
  customerPhone: body?.call?.customer?.number  ?? body?.customer?.number ?? '',
  customerName:  body?.call?.customer?.name    ?? body?.customer?.name   ?? 'Customer',
  callDuration:  Number(body?.durationSeconds  ?? body?.call?.duration   ?? 0),
  callStatus:    body?.call?.status            ?? body?.status            ?? 'unknown',
  endedReason:   body?.call?.endedReason       ?? body?.endedReason       ?? 'unknown',
  summary:       (body?.summary                ?? body?.call?.analysis?.summary ?? '').trim(),
  transcript:    (body?.transcript             ?? body?.call?.transcript  ?? '').trim(),
  structuredData:
    body?.call?.analysis?.structuredData   ??
    body?.structuredData                   ??
    body?.call?.analysis?.structuredOutput ??
    body?.structuredOutput                 ??
    {},
  startedAt: body?.call?.startedAt ?? new Date().toISOString(),
  endedAt:   body?.call?.endedAt   ?? new Date().toISOString(),
};

// --- IDEMPOTENCY: check if this leadId was already processed
// (The duplicate-row check happens in the Sheets lookup node that follows;
//  here we set a flag so downstream nodes can skip safely)
const isDuplicateWebhook = false; // Overridden by downstream Sheets check node

const locationInfo = callData.structuredData?.customerLocation ?? {};
const customerLocation = {
  serviceLocation:   (locationInfo?.serviceLocation ?? 'Unknown').trim(),
  city:              (locationInfo?.city            ?? '').trim(),
  areaReference:     (locationInfo?.areaReference   ?? '').trim(),
  locationConfirmed: locationInfo?.locationConfirmed ?? false,
};

const serviceLocationRaw = customerLocation.serviceLocation;
const locationDisplay =
  (serviceLocationRaw.length > 0 && serviceLocationRaw !== 'Unknown')
    ? serviceLocationRaw
    : customerLocation.city.length > 0
      ? customerLocation.city
      : customerLocation.areaReference.length > 0
        ? customerLocation.areaReference
        : 'Area not captured';

const GHOST_ENDED_REASONS = ['no-answer', 'voicemail', 'machine', 'no-answer-machine', 'customer-hangup-early'];
const isGhost =
  callData.callDuration < 15 ||
  callData.summary.length === 0 ||
  GHOST_ENDED_REASONS.includes(callData.endedReason.toLowerCase());

// Life-safety emergencies (gas, fire, CO) require 911 direction to customer
const LIFE_SAFETY_KEYWORDS = ['gas', 'gas smell', 'fire', 'smoke', 'carbon monoxide', 'co detector', 'sparks'];
const EMERGENCY_KEYWORDS = [
  'emergency', 'urgent', 'leak', 'no heat', 'burst',
  'flooding', 'flood', 'no hot water', 'broken pipe',
  'sewage', 'overflow', 'no ac', 'no air',
  ...LIFE_SAFETY_KEYWORDS
];
const searchText = (
  callData.summary + ' ' +
  (callData.structuredData?.serviceType ?? '') + ' ' +
  (callData.structuredData?.issueDescription ?? '') + ' ' +
  callData.transcript
).toLowerCase();
const structuredEmergency = callData.structuredData?.isEmergency === true;
const keywordEmergency = EMERGENCY_KEYWORDS.some(kw => searchText.includes(kw));
const isEmergency = structuredEmergency || keywordEmergency;
const isLifeSafety = LIFE_SAFETY_KEYWORDS.some(kw => searchText.includes(kw));

const sd = callData.structuredData;
const isQualified = !isGhost && (
  sd?.appointmentRequested === true ||
  sd?.isInterested === true ||
  (sd?.serviceType && sd.serviceType.length > 0) ||
  callData.summary.length > 40
);

return [{
  json: {
    ...callData,
    customerLocation,
    locationDisplay,
    isGhost,
    isEmergency,
    isLifeSafety,
    isQualified,
    isDuplicateWebhook,
    resolvedPath: isGhost ? 'GHOST' : isEmergency ? 'EMERGENCY' : isQualified ? 'QUALIFIED' : 'UNQUALIFIED',
    processedAt: new Date().toISOString(),
  }
}];

